public static void main(String[] args) throws IOException {
    BufferedReader buf = new BufferedReader(new InputStreamReader(System.in));
    int t = Integer.parseInt(buf.readLine());
    List<User> users = new ArrayList<>();
    long total = 0;
    for (int i = 0; i < t; i++) {
        String[] s = buf.readLine().trim().split(" ");
        String name = s[0];
        int rating = Integer.parseInt(s[1]);
        total += rating;
        users.add(new User(name, rating));
    }
    users.sort(Comparator.comparing(user -> user.name));
    total %= t;
    System.out.println(users.get((int) total).name);
}

static class User {
    String name;
    int rating;

    User(String name, int rating) {
        this.name = name;
        this.rating = rating;
    }
}
